    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        fn_specNotCheck(selfVar)  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_specNotCheck — as-is 공통(폼 전역 의존) — 반입 보류

