///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_Chk_form
 * @description Chk form 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_Chk_form = async function () {
    const sbmOptions = {
        id: "tx_Chk_form",
        method: "post",
        action: "/stdcd/mfCp.do?method=cpModifyProcess",
        ref: "dma_ChkFormReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name mpd_files_selectCallback
 * @description mpd files select Callback 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.mpd_files_selectCallback = function (data) { const d = $c.util.getComponent('dlt_files'); if (!d) { return; } const rows = []; for (let i = 0; i < (data || []).length; i++) { rows.push({ FILE_NM: data[i].name, FILE_SIZE: String(data[i].size), CHK: '' }); } if (rows.length) { d.insertJSON(d.getRowCount(), rows); } };

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name emailCheck
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.emailCheck = function (obj) { try { const t = (obj && obj.value != null) ? obj : ((obj && (obj.target || obj.srcElement)) || null); if (t && t.value != null) { t.value = String(t.value).replace(/[^A-Za-z0-9.@_%+\\-]/g, ''); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'authored-fn' }); return; } };

/**
 * @method
 * @name checkRadio
 * @description check Radio 처리
 * @returns {void}
 * @hidden N
 */
scwin.checkRadio = function () {
    const checkRdArr = $('input[key=checkRd]');
    const leng = checkRdArr.length;
    if (leng > 0) {
        for (let i = 0; i < leng; i++) {
            const vl = $(checkRdArr[i]).val();
            const target = $(checkRdArr[i]).attr("target");
            const checkId = $('label[for*=' + target + ']:contains(' + vl + ')').attr("for");
            const tObj = $('#' + checkId);
            if (tObj.length > 0) {
                $('#' + checkId)[0].checked = true;
            }
        }
    }
};

/**
 * @method
 * @name open_select_inst_cd
 * @description open select inst cd 처리
 * @param {Object} obj 컴포넌트
 * @param {*} check check
 * @returns {void}
 * @hidden N
 */
scwin.open_select_inst_cd = function (obj, check) {
    if (check === '1') {
        if ($(obj)[0].checked) {
            $c.util.getComponent('ipt_dcInstCd').setValue("9109");
            $c.util.getComponent('ipt_dcInstNm').setValue("한국예탁결재원");
            $('#creditPop').css("visibility", "hidden");
        }
    } else {
        $c.util.getComponent('ipt_dcInstCd').setValue("");
        $c.util.getComponent('ipt_dcInstNm').setValue("");
        $('#creditPop').css("visibility", "visible");
    }
};

/**
 * @method
 * @name checkSelect
 * @description check Select 처리
 * @returns {void}
 * @hidden N
 */
scwin.checkSelect = function () {
    const checkStArr = $('input[key=checkSt]');
    const leng = checkStArr.length;
    if (leng > 0) {
        for (let i = 0; i < leng; i++) {
            const vl = $(checkStArr[i]).val();
            const target = $(checkStArr[i]).attr("target");
            const tObj = $('#' + target);
            if (tObj.length > 0) {
                if (target === 'byinst_credit_valu_grd1' || target === 'byinst_credit_valu_grd2' || target === 'byinst_credit_valu_grd3' || target === 'byinst_credit_valu_grd4') {
                    $('#' + target).find("option[value='" + vl + "']").attr("selected", true);
                } else {
                    $('#' + target).find('option:contains(' + vl + ')').attr("selected", true);
                }
            }
        }
    }
};

/**
 * @method
 * @name checkRegData
 * @description check Reg Data 처리
 * @returns {void}
 * @hidden N
 */
scwin.checkRegData = function () {
    const vl = dma_hiddenStore.get("ipt_regType");
    if (vl !== '') {
        const tObj = $('input[name=std_cd_apct_tp_cd][value="' + vl + '"]');
        if (tObj.length > 0) {
            $(tObj)[0].checked = true;
        }
    }
    const email = dma_hiddenStore.get("ipt_regEmail");
    if (email !== '') {
        const emails = email.split("@");
        if (emails.length > 0) {
            $c.util.getComponent('ipt_email01').setValue(emails[0]);
        }
        if (emails.length > 1) {
            $c.util.getComponent('ipt_email02').setValue(emails[1]);
        }
    }
    const tel = dma_hiddenStore.get("ipt_regTel");
    if (tel !== '') {
        const tels = tel.split("-");
        if (tels.length > 0) {
            $c.util.getComponent('ipt_ph01').setValue(tels[0]);
        }
        if (tels.length > 1) {
            $c.util.getComponent('ipt_ph02').setValue(tels[1]);
        }
        if (tels.length > 2) {
            $c.util.getComponent('ipt_ph03').setValue(tels[2]);
        }
    }
    const fax = dma_hiddenStore.get("ipt_regFax");
    if (fax !== '') {
        const faxs = fax.split("-");
        if (faxs.length > 0) {
            $c.util.getComponent('ipt_fax01').setValue(faxs[0]);
        }
        if (faxs.length > 1) {
            $c.util.getComponent('ipt_fax02').setValue(faxs[1]);
        }
        if (faxs.length > 2) {
            $c.util.getComponent('ipt_fax03').setValue(faxs[2]);
        }
    }
    const hpNo = $c.util.getComponent('ipt_encrypCellphoneNo').getValue();
    const hpNos = hpNo.split("-");
    if (hpNos.length > 0) {
        $c.util.getComponent('ipt_encrypCellphoneNo1').setValue(hpNos[0]);
    }
    if (hpNos.length > 1) {
        $c.util.getComponent('ipt_encrypCellphoneNo2').setValue(hpNos[1]);
    }
    if (hpNos.length > 1) {
        $c.util.getComponent('ipt_encrypCellphoneNo3').setValue(hpNos[2]);
    }
};

