/**
 * @method
 * @name dataValidation
 * @description data Validation 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dataValidation = async function () {
    const expDd = $c.util.getComponent('cal_expDd').getValue();
    const isuDd = dma_hiddenStore.get("isu_dd");
    if ($c.str.getByteLength(expDd) === 0) {
        await $c.win.alert("만기일을 입력하세요.");
        $c.util.getComponent("cal_expDd").focus();
        return true;
    }
    if (Number(expDd) < Number(isuDd)) {
        await $c.win.alert("상환일(만기일)은 발행일 이후로 입력하세요.");
        $c.util.getComponent("cal_expDd").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_expPayAmt').getValue()) === 0) {
        await $c.win.alert("발행금액을 입력하세요.");
        ($c.util.getComponent('ipt_expPayAmt') && $c.util.getComponent('ipt_expPayAmt').setFocus ? $c.util.getComponent('ipt_expPayAmt').setFocus() : $c.util.getComponent('ipt_expPayAmt').focus());
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_yy1BasYd').getValue()) === 0) {
        await $c.win.alert("표면이자율을 입력하세요.");
        $c.util.getComponent("ipt_yy1BasYd").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_dcSales').getValue()) === 0) {
        await $c.win.alert("할인매출액을 입력하세요.");
        ($c.util.getComponent('ipt_dcSales') && $c.util.getComponent('ipt_dcSales').setFocus ? $c.util.getComponent('ipt_dcSales').setFocus() : $c.util.getComponent('ipt_dcSales').focus());
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_dcRt').getValue()) === 0) {
        await $c.win.alert("할인율을 입력하세요.");
        $c.util.getComponent("ipt_dcRt").focus();
        return true;
    }
    let exp_pay_amt = $c.util.getComponent('ipt_expPayAmt').getValue().toString();
    exp_pay_amt = parseInt(Del_MoneyComma_Value(exp_pay_amt));
    let dc_sales = $c.util.getComponent('ipt_dcSales').getValue().toString();
    dc_sales = parseInt(Del_MoneyComma_Value(dc_sales));
    if (exp_pay_amt === 0) {
        await $c.win.alert("발행금액에 0을 입력 할 수 없습니다.");
        $c.util.getComponent('ipt_expPayAmt').setValue("");
        ($c.util.getComponent('ipt_expPayAmt') && $c.util.getComponent('ipt_expPayAmt').setFocus ? $c.util.getComponent('ipt_expPayAmt').setFocus() : $c.util.getComponent('ipt_expPayAmt').focus());
        return true;
    }
    if (dc_sales === 0) {
        await $c.win.alert("할인매출액에 0을 입력 할 수 없습니다.");
        $c.util.getComponent('ipt_dcSales').setValue("");
        ($c.util.getComponent('ipt_dcSales') && $c.util.getComponent('ipt_dcSales').setFocus ? $c.util.getComponent('ipt_dcSales').setFocus() : $c.util.getComponent('ipt_dcSales').focus());
        return true;
    }
    if (dc_sales > exp_pay_amt) {
        await $c.win.alert("할인매출액이 발행금액보다 클 수 없습니다.");
        ($c.util.getComponent('ipt_dcSales') && $c.util.getComponent('ipt_dcSales').setFocus ? $c.util.getComponent('ipt_dcSales').setFocus() : $c.util.getComponent('ipt_dcSales').focus());
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_dcInstCd').getValue()) === 0) {
        await $c.win.alert("할인기관을 입력하세요.");
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_nusualIsuCondContn').getValue()) > 0) {
        if ($c.util.getComponent('ipt_nusualIsuCondContn').getValue().indexOf("\t") > -1 || $c.util.getComponent('ipt_nusualIsuCondContn').getValue().indexOf("\n") > -1 || $c.util.getComponent('ipt_nusualIsuCondContn').getValue().indexOf("\r") > -1) {
            await $c.win.alert("특이발행조건에 '탭문자' 혹은 '개행문자'가 포함되어있습니다.\n다시 입력해 주십시오.");
            $("#ipt_nusualIsuCondContn").select();
            return true;
        }
    }
    if (!$('input[name=group]').is(":checked")) {
        await $c.win.alert("'그룹'을 선택하세요.");
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('slc_attr01').getValue()) === 0) {
        await $c.win.alert("'1차속성'을 선택하세요.");
        $c.util.getComponent("slc_attr01").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('slc_attr02').getValue()) === 0) {
        await $c.win.alert("'2차속성'을 선택하세요.");
        $c.util.getComponent("slc_attr02").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('slc_attr03').getValue()) === 0) {
        await $c.win.alert("'3차속성'을 선택하세요.");
        $c.util.getComponent("slc_attr03").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('slc_attr04').getValue()) === 0) {
        await $c.win.alert("'4차속성'을 선택하세요.");
        $c.util.getComponent("slc_attr04").focus();
        return true;
    }
    if (!await scwin.dataLenCheck()) {
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_applComNm').getValue()) === 0) {
        await $c.win.alert("소속기관을 입력하세요.");
        $c.util.getComponent("ipt_applComNm").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_apctNm').getValue()) === 0) {
        await $c.win.alert("이름을 입력하세요.");
        $c.util.getComponent("ipt_apctNm").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_apctNm').getValue()) > 20) {
        await $c.win.alert("신청인 이름을 한글 10자, 영문 20자이내로 입력해 주세요");
        $c.util.getComponent("ipt_apctNm").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_ph01').getValue()) === 0) {
        await $c.win.alert("전화번호를 입력하세요.");
        $c.util.getComponent("ipt_ph01").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_ph02').getValue()) === 0) {
        await $c.win.alert("전화번호를 입력하세요.");
        $c.util.getComponent("ipt_ph02").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_ph03').getValue()) === 0) {
        await $c.win.alert("전화번호를 입력하세요.");
        $c.util.getComponent("ipt_ph03").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_fax01').getValue()) > 0 || $c.str.getByteLength($c.util.getComponent('ipt_fax02').getValue()) > 0 || $c.str.getByteLength($c.util.getComponent('ipt_fax03').getValue()) > 0) {
        if ($c.str.getByteLength($c.util.getComponent('ipt_fax01').getValue()) === 0) {
            await $c.win.alert("신청인 팩스번호를 입력하세요");
            $c.util.getComponent("ipt_fax01").focus();
            return true;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_fax02').getValue()) === 0) {
            await $c.win.alert("신청인 팩스번호를 입력하세요");
            $c.util.getComponent("ipt_fax02").focus();
            return true;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_fax03').getValue()) === 0) {
            await $c.win.alert("신청인 팩스번호를 입력하세요");
            $c.util.getComponent("ipt_fax03").focus();
            return true;
        }
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_email01').getValue()) === 0) {
        await $c.win.alert("이메일을 입력하세요.");
        $c.util.getComponent("ipt_email01").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_email02').getValue()) === 0) {
        await $c.win.alert("이메일을 입력하세요.");
        $c.util.getComponent("ipt_email02").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_email01').getValue() + "" + $c.util.getComponent('ipt_email02').getValue()) > 40) {
        await $c.win.alert("신청인 이메일을 한글 20자, 영문 40자이내로 입력하세요");
        $c.util.getComponent("ipt_email01").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypCellphoneNo1').getValue()) === 0) {
        await $c.win.alert("신청인 휴대전화번호를 입력하세요");
        $c.util.getComponent("ipt_encrypCellphoneNo1").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypCellphoneNo2').getValue()) === 0) {
        await $c.win.alert("신청인 휴대전화번호를 입력하세요");
        $c.util.getComponent("ipt_encrypCellphoneNo2").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypCellphoneNo3').getValue()) === 0) {
        await $c.win.alert("신청인 휴대전화번호를 입력하세요");
        $c.util.getComponent("ipt_encrypCellphoneNo3").focus();
        return true;
    }
    return false;
};

/**
 * @method
 * @name dataLenCheck
 * @description data Len Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dataLenCheck = async function () {
    let len = $c.str.getByteLength($c.util.getComponent('ipt_brnNm').getValue());
    if (len === 0) {
        await $c.win.alert("지점명을 입력하세요.");
        $c.util.getComponent("ipt_brnNm").focus();
        return false;
    }
    if (len > 80) {
        await $c.win.alert("지점명은 한글40자, 영문80자 이내로 입력하세요.");
        $c.util.getComponent("ipt_brnNm").focus();
        return false;
    }
    len = $c.str.getByteLength($c.util.getComponent('ipt_delRsn').getValue());
    if (len === 0) {
        await $c.win.alert("수정사유를 입력하세요.");
        $c.util.getComponent("ipt_delRsn").focus();
        return false;
    }
    if (len < 10) {
        await $c.win.alert("수정사유는 한글5자, 영문10자 이상 입력하세요.");
        $c.util.getComponent("ipt_delRsn").focus();
        return false;
    }
    if (len > 60) {
        await $c.win.alert("수정사유는 한글30자, 영문60자 이내로 입력하세요.");
        $c.util.getComponent("ipt_delRsn").focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name Chk_form
 * @description Chk form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.Chk_form = async function () {
    const chkBl = await scwin.dataValidation();
    if (chkBl) {
        return;
    }
    if ($c.util.getComponent('ipt_fisnMakeYn').getValue() !== 'Y') {
        await $c.win.alert("[FISN생성] 버튼으로 'FISN'을 확인하세요.");
        $c.util.getComponent("ipt_fisnVal").focus();
        return;
    }
    if (!!!(($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount && ($c.util.getComponent('dlt_files')).getRowCount() > 0)) {
        return;
    }
    const totFileSize = (Math.round(((($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount) ? Array.from({ length: ($c.util.getComponent('dlt_files')).getRowCount() }, function (x, i) { return Number(($c.util.getComponent('dlt_files')).getCellData(i, 'FILE_SIZE')) || 0; }).reduce(function (a, b) { return a + b; }, 0) : 0) / (1024 * 1024) * 100) / 100);
    if (totFileSize > 100) {
        await $c.win.alert("전체 첨부파일의 크기는 최대 100MB까지 허용됩니다.\n현재 크기 = " + totFileSize + "MB");
        return;
    }
    $c.util.getComponent('ipt_expPayAmt').setValue(($c.util.getComponent("ipt_expPayAmt").getValue() || '').replace(/\,/g, ''));
    $c.util.getComponent('ipt_dcSales').setValue(($c.util.getComponent("ipt_dcSales").getValue() || '').replace(/\,/g, ''));
    const telNo = $c.util.getComponent('ipt_ph01').getValue() + "-" + $c.util.getComponent('ipt_ph02').getValue() + "-" + $c.util.getComponent('ipt_ph03').getValue();
    const faxNo = $c.util.getComponent('ipt_fax01').getValue() + "-" + $c.util.getComponent('ipt_fax02').getValue() + "-" + $c.util.getComponent('ipt_fax03').getValue();
    const emailNo = $c.util.getComponent('ipt_email01').getValue() + '@' + $c.util.getComponent('ipt_email02').getValue();
    const encryp_cellphone_no = $c.util.getComponent('ipt_encrypCellphoneNo1').getValue() + "-" + $c.util.getComponent('ipt_encrypCellphoneNo2').getValue() + "-" + $c.util.getComponent('ipt_encrypCellphoneNo3').getValue();
    $c.util.getComponent('ipt_encrypApctEmail').setValue(emailNo);
    $c.util.getComponent('ipt_apctTelNo').setValue(telNo);
    $c.util.getComponent('ipt_apctFaxNo').setValue(faxNo);
    $c.util.getComponent('ipt_encrypCellphoneNo').setValue(encryp_cellphone_no);
    if (await $c.win.confirm("수정하시겠습니까?")) {
        await scwin.tx_Chk_form();
    }
};

